import os
import re
import json
from typing import List, Dict, Any, Tuple, Optional

import requests


PERSPECTIVE_API_URL = "https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze"


def _iter_sentence_spans(text: str) -> List[Tuple[int, int]]:
    spans = []
    start = 0
    for match in re.finditer(r"(?<=[.!?])\s+", text):
        end = match.start()
        if end > start:
            spans.append((start, end))
        start = match.end()
    if start < len(text):
        spans.append((start, len(text)))
    return spans if spans else [(0, len(text))]


def _build_request(text: str, requested_attributes: Dict[str, Dict[str, Any]]) -> Dict[str, Any]:
    return {
        "comment": {"text": text},
        "requestedAttributes": requested_attributes,
        "languages": ["en"],
        "doNotStore": True,
    }


def _call_perspective(text: str, requested_attributes: Dict[str, Dict[str, Any]], api_key: str) -> Dict[str, Any]:
    params = {"key": api_key}
    payload = _build_request(text, requested_attributes)
    resp = requests.post(PERSPECTIVE_API_URL, params=params, json=payload, timeout=30)
    resp.raise_for_status()
    return resp.json()


def _attribute_scores(resp_json: Dict[str, Any]) -> Dict[str, float]:
    scores = {}
    attr = resp_json.get("attributeScores", {})
    for k, v in attr.items():
        try:
            scores[k] = float(v["summaryScore"]["value"])
        except Exception:
            continue
    return scores


def _flag_spans(text: str, api_key: str, threshold: float = 0.8) -> List[Dict[str, Any]]:
    requested_attributes = {
        "TOXICITY": {},
        "INSULT": {},
        "PROFANITY": {},
        "THREAT": {},
        "SEXUALLY_EXPLICIT": {},
        "IDENTITY_ATTACK": {},
    }

    spans = _iter_sentence_spans(text)
    findings = []

    for start, end in spans:
        span_text = text[start:end]
        if not span_text.strip():
            continue
        try:
            resp = _call_perspective(span_text, requested_attributes, api_key)
            scores = _attribute_scores(resp)
        except Exception:
            continue

        max_attr = None
        max_score = 0.0
        for attr_name, score in scores.items():
            if score > max_score:
                max_score = score
                max_attr = attr_name

        if max_attr and max_score >= threshold:
            findings.append(
                {
                    "start": start,
                    "end": end,
                    "text": span_text,
                    "label": max_attr,
                    "score": max_score,
                }
            )

    return findings


def _redact_text(text: str, findings: List[Dict[str, Any]], replacement: str = "[REDACTED]") -> str:
    if not findings:
        return text

    merged = []
    for item in sorted(findings, key=lambda x: (x["start"], x["end"])):
        if not merged or item["start"] > merged[-1]["end"]:
            merged.append([item["start"], item["end"]])
        else:
            merged[-1][1] = max(merged[-1][1], item["end"])

    parts = []
    cursor = 0
    for start, end in merged:
        if cursor < start:
            parts.append(text[cursor:start])
        parts.append(replacement)
        cursor = end
    if cursor < len(text):
        parts.append(text[cursor:])
    return "".join(parts)


def flag_or_redact_unsafe_spans(
    text: str,
    redact: bool = False,
    threshold: float = 0.8,
    api_key: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Uses Perspective API to flag or redact unsafe spans in text.

    Returns:
        {
            "text": original text,
            "unsafe_spans": [...],
            "redacted_text": ... (if redact=True)
        }
    """
    key = api_key or os.getenv("PERSPECTIVE_API_KEY")
    if not key:
        raise ValueError("Missing Perspective API key. Set PERSPECTIVE_API_KEY or pass api_key.")

    findings = _flag_spans(text, key, threshold=threshold)
    result = {"text": text, "unsafe_spans": findings}

    if redact:
        result["redacted_text"] = _redact_text(text, findings)

    return result
